// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    receive() external payable {}

    function testFuzz_property(uint256 amount, address funder) public {
        vm.assume(funder != address(0));
        amount = bound(amount, 1, 1 ether);

        // funder deposits via the fallback, which increments depositsCount once
        vm.deal(funder, amount);
        vm.prank(funder);
        (bool sent, ) = address(c).call{value: amount}("");
        assertTrue(sent);

        // owner withdraws everything; this must NOT touch depositsCount
        vm.prank(c.owner());
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        assertTrue(ok && c.depositsCount() == 1);
    }
}
